fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(word.len());
    
    // Check the first character and capitalize if necessary
    if let Some(&first_char) = word.get(0) {
        if first_char.is_ascii_lowercase() {
            result.push('A'); // Replace with 'A' if it's lowercase
        } else {
            result.push(first_char); // Keep it unchanged if it's uppercase
        }
    }
    
    // Copy the rest of the characters
    for &c in &word[1..] {
        result.push(c);
    }
    
    result
}